'use client';

import { useState, useEffect, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  Loader2,
  Sparkles,
  AlertCircle,
  MessageSquare,
  FileText,
  User,
  Wand2,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { createEstimate, getConversationalResponse } from './actions';
import type { InitialEstimateOutput, InitialEstimateInput } from '@/ai/schemas/initial-estimate';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';

const formSchema = z.object({
  squareFootage: z.coerce
    .number()
    .positive({ message: 'Square footage must be a positive number.' }),
  ceilingHeight: z.coerce
    .number()
    .positive({ message: 'Ceiling height must be a positive number.' }),
  ceilingType: z.enum(['Standard', 'Open']),
  planType: z.enum(['Open Plan', 'Mixed Use']),
  privateOffices: z.coerce
    .number()
    .int()
    .nonnegative({ message: 'Number of offices cannot be negative.' }),
});

type Message = { role: 'model' | 'user'; content: string };

function ChatInterface({
  messages,
  onSubmit,
  isLoading,
}: {
  messages: Message[];
  onSubmit: (content: string) => void;
  isLoading: boolean;
}) {
  const [input, setInput] = useState('');
  const scrollAreaRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollAreaRef.current) {
      scrollAreaRef.current.scrollTo({
        top: scrollAreaRef.current.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [messages]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSubmit(input);
      setInput('');
    }
  };
  return (
    <Card>
      <CardHeader>
        <CardTitle>Conversational Estimate</CardTitle>
        <CardDescription>
          Answer a few questions to generate your budget estimate.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="h-[400px] flex flex-col">
          <ScrollArea className="flex-1 pr-4" ref={scrollAreaRef}>
            <div className="space-y-6">
              {messages.map((message, index) => (
                <div
                  key={index}
                  className={cn(
                    'flex items-start gap-3',
                    message.role === 'user' && 'justify-end'
                  )}
                >
                  {message.role === 'model' && (
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        <Wand2 className="h-4 w-4" />
                      </AvatarFallback>
                    </Avatar>
                  )}
                  <div
                    className={cn(
                      'rounded-lg p-3 max-w-[80%]',
                      message.role === 'model'
                        ? 'bg-muted'
                        : 'bg-primary text-primary-foreground'
                    )}
                  >
                    <p className="text-sm">{message.content}</p>
                  </div>
                  {message.role === 'user' && (
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        <User className="h-4 w-4" />
                      </AvatarFallback>
                    </Avatar>
                  )}
                </div>
              ))}
               {isLoading && messages.length > 0 && messages[messages.length-1].role === 'user' && (
                 <div className="flex items-start gap-3">
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        <Wand2 className="h-4 w-4" />
                      </AvatarFallback>
                    </Avatar>
                    <div className="rounded-lg p-3 bg-muted">
                        <Loader2 className="h-5 w-5 animate-spin" />
                    </div>
                 </div>
               )}
            </div>
          </ScrollArea>
          <form onSubmit={handleFormSubmit} className="mt-4 flex gap-2">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your message..."
              className="flex-1"
              rows={1}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleFormSubmit(e);
                }
              }}
              disabled={isLoading}
            />
            <Button type="submit" disabled={isLoading || !input.trim()}>
              Send
            </Button>
          </form>
        </div>
      </CardContent>
    </Card>
  );
}

function FormInput({ form, onSubmit, isLoading }: { form: any; onSubmit: any; isLoading: boolean }) {
    return (
        <Card>
            <CardHeader>
              <CardTitle>Project Details</CardTitle>
              <CardDescription>
                Enter your commercial renovation project details to generate a budget estimate.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Form {...form}>
                <form
                  onSubmit={form.handleSubmit(onSubmit)}
                  className="space-y-6"
                >
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="squareFootage"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Project Square Footage</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 5000" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="ceilingHeight"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Ceiling Height (ft)</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 12" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                   <FormField
                      control={form.control}
                      name="ceilingType"
                      render={({ field }) => (
                      <FormItem>
                          <FormLabel>Ceiling Type</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                              <SelectTrigger>
                              <SelectValue placeholder="Select a ceiling type" />
                              </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                              <SelectItem value="Standard">Standard (Drywall/Tiles)</SelectItem>
                              <SelectItem value="Open">Open (Exposed Ductwork)</SelectItem>
                          </SelectContent>
                          </Select>
                          <FormDescription>
                          HVAC costs are higher for open ceilings.
                          </FormDescription>
                          <FormMessage />
                      </FormItem>
                      )}
                  />
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="planType"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Plan Type</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select a plan type" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="Open Plan">Open Plan</SelectItem>
                              <SelectItem value="Mixed Use">Mixed Use</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="privateOffices"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Private Offices</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 3" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                  <Button type="submit" disabled={isLoading} className="w-full">
                    {isLoading ? (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    ) : (
                      <Sparkles className="mr-2 h-4 w-4" />
                    )}
                    Generate Estimate
                  </Button>
                </form>
              </Form>
            </CardContent>
          </Card>
    )
}

function CollectedInfoCard({ data }: { data: Partial<InitialEstimateInput> }) {
  const fields = [
    { key: 'squareFootage', label: 'Square Footage' },
    { key: 'planType', label: 'Plan Type' },
    { key: 'privateOffices', label: 'Private Offices' },
    { key: 'ceilingType', label: 'Ceiling Type' },
    { key: 'ceilingHeight', label: 'Ceiling Height' },
  ];

  return (
    <Card>
      <CardHeader>
        <CardTitle>Collected Information</CardTitle>
        <CardDescription>
          Here's what I've gathered from our conversation so far.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        {fields.map(field => {
          const value = data[field.key as keyof typeof data];
          return (
            <div key={field.key} className="flex justify-between items-center text-sm">
              <span className="text-muted-foreground">{field.label}:</span>
              {value ? (
                <span className="font-medium">{String(value)}</span>
              ) : (
                <span className="italic text-muted-foreground/70">Not provided</span>
              )}
            </div>
          );
        })}
      </CardContent>
    </Card>
  );
}

export default function EstimatePage() {
  const [view, setView] = useState<'chat' | 'form'>('chat');
  const [isLoading, setIsLoading] = useState(false);
  const [estimate, setEstimate] = useState<InitialEstimateOutput | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [collectedData, setCollectedData] = useState<Partial<InitialEstimateInput>>({});
  const { toast } = useToast();

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      squareFootage: undefined,
      ceilingHeight: undefined,
      privateOffices: undefined,
      planType: 'Open Plan',
      ceilingType: 'Standard',
    },
  });

  const handleConversationalSubmit = async (content: string) => {
    setIsLoading(true);
    setEstimate(null);
    const newHistory = [...messages, { role: 'user' as const, content }];
    setMessages(newHistory);

    try {
      const result = await getConversationalResponse(newHistory, collectedData);
      setMessages((prev) => [...prev, { role: 'model', content: result.response }]);
      setCollectedData(result.updatedData);

      if (result.isComplete && result.updatedData) {
        const fullData = formSchema.parse(result.updatedData);
        const finalResult = await createEstimate(fullData);
        setEstimate(finalResult);
      }
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'An error occurred',
        description: 'The AI assistant is having trouble. Please try again or switch to the form.',
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (view === 'chat' && messages.length === 0) {
      setMessages([
        {
          role: 'model',
          content:
            "Welcome to RenoAI! I can help you create a budget estimate for your commercial renovation project. To get started, what's the total square footage of the project area?",
        },
      ]);
    }
  }, [view, messages.length]);

  async function onFormSubmit(values: z.infer<typeof formSchema>) {
    setIsLoading(true);
    setEstimate(null);
    try {
      const result = await createEstimate(values);
      setEstimate(result);
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'An error occurred',
        description:
          'Failed to generate the estimate. Please try again later.',
      });
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h1 className="text-3xl font-bold tracking-tight font-headline">New Estimate</h1>
        <div className="flex items-center gap-2">
           <Button variant={view === 'chat' ? 'default' : 'outline'} size="sm" onClick={() => setView('chat')}>
              <MessageSquare className="mr-2 h-4 w-4" />
              Chat
            </Button>
            <Button variant={view === 'form' ? 'default' : 'outline'} size="sm" onClick={() => setView('form')}>
              <FileText className="mr-2 h-4 w-4" />
              Form
            </Button>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div>
          {view === 'chat' ? (
            <ChatInterface messages={messages} onSubmit={handleConversationalSubmit} isLoading={isLoading} />
          ) : (
            <FormInput form={form} onSubmit={onFormSubmit} isLoading={isLoading} />
          )}
        </div>
        <div>
          <div className="space-y-8">
            {isLoading && !estimate && (
              <Card>
                <CardHeader>
                  <CardTitle>Generating Your Estimate...</CardTitle>
                  <CardDescription>
                    Our AI is analyzing your project. Please wait a moment.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2 animate-pulse">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-2/3"></div>
                  </div>
                   <div className="space-y-2 animate-pulse delay-150">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-4/5"></div>
                  </div>
                </CardContent>
              </Card>
            )}
            {estimate ? (
              <>
                <Card className="bg-green-50 dark:bg-green-900/20 border-accent">
                  <CardHeader>
                    <CardTitle>Estimated Budget</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-5xl font-bold text-green-700 dark:text-green-400">
                      {estimate.estimatedBudget}
                    </p>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader>
                    <CardTitle>Assumptions</CardTitle>
                    <CardDescription>
                      The estimate is based on the following assumptions:
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <p className="text-muted-foreground whitespace-pre-wrap">{estimate.assumptions}</p>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader className="flex flex-row items-center gap-2">
                    <AlertCircle className="h-5 w-5 text-amber-500" />
                    <CardTitle>Disclaimer</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-muted-foreground">
                      {estimate.disclaimer}
                    </p>
                  </CardContent>
                </Card>
              </>
            ) : !isLoading && (
              <>
                {view === 'chat' ? (
                  <CollectedInfoCard data={collectedData} />
                ) : (
                  <Card className="flex flex-col items-center justify-center text-center p-8 min-h-[400px]">
                      <CardHeader>
                        <Sparkles className="h-16 w-16 mx-auto text-muted-foreground/50" />
                        <CardTitle className="mt-4">Your AI-Powered Estimate</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <p className="text-muted-foreground">
                          Your generated budget report will appear here once you enter your project details.
                        </p>
                      </CardContent>
                    </Card>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
